// Concatenates supabase/migrations into supabase/setup.sql, a single file that can be
// pasted into the Supabase SQL Editor once on a new project. tests/setup-sql.test.ts
// keeps it in sync.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export const HEADER = `-- Gio database setup: every migration in supabase/migrations, in order.
-- Run this once on a new Supabase project (SQL Editor > New query > paste > Run).
-- Generated by scripts/build-setup-sql.mjs; edit the migrations, not this file.
`;

export function buildSetupSql(root) {
  const dir = join(root, "supabase/migrations");
  const parts = readdirSync(dir)
    .filter((f) => f.endsWith(".sql"))
    .sort()
    .map((f) => `\n-- ===== ${f} =====\n\n${readFileSync(join(dir, f), "utf8").trimEnd()}\n`);
  return HEADER + parts.join("");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const root = process.cwd();
  writeFileSync(join(root, "supabase/setup.sql"), buildSetupSql(root));
  console.log("Wrote supabase/setup.sql");
}
